jQuery(document).ready(function($){updateHeaderCartBadgeValue();handleHeaderCartIconClick();handleHeaderUserCtaClick();handleResponsiveMenuButtonClick();handleResponsiveMenuCloseButtonClick()});function updateHeaderCartBadgeValue(){if($(".golzari-header-cart").length<1){return false}if(typeof localizedData=="undefined"||typeof localizedData.cartQuantity=="undefined"){return false}if(localizedData.cartQuantity>0){$(".cart-counter-badge").html(localizedData.cartQuantity);$(".golzari-header-cart").addClass("show-badge")}}function handleHeaderCartIconClick(){if($(".golzari-header-cart").length<1){return false}$(".golzari-header-cart").on("click",function(e){e.preventDefault();window.location.href=localizedData.cartUrl})}function handleHeaderUserCtaClick(){if($(".golzari-header-user-info-cta.logged-in").length<1){return false}$(".golzari-header-user-info-cta.logged-in").on("click",function(e){e.stopPropagation();$(this).toggleClass("show-drop-down");$(".golzari-header-user-info-drop-down").toggleClass("show-drop-down");$(".responsive-menu").removeClass("show")})}function handleResponsiveMenuButtonClick(){if($(".golzari-responsive-menu-toggle").length<1){return false}$(".golzari-responsive-menu-toggle").on("click",function(){$(".responsive-menu").toggleClass("show");$(this).toggleClass("show-drop-down");$(".golzari-header-user-info-cta,.golzari-header-user-info-drop-down").removeClass("show-drop-down")})}function handleResponsiveMenuCloseButtonClick(){if($(".responsive-menu-close-button").length<1){return false}$(".responsive-menu-close-button").on("click",function(){$(".responsive-menu").removeClass("show")})}